          "text": "从 「 乖乖水 」「 听话水 」 的名字可见，是让服用者失去反抗能力甚至失去意识，从而达到任人摆布的目的。不论其名称如何，这类 迷幻春药 的主要成分无外乎三大类物质，即氟硝西泮、三唑仑以及γ-羟基丁酸及其类似物。而这三类物质，其本质就是具有镇静、催眠以及促进遗忘的精神药物。本品具有 致幻催眠效果，俗称洗脑药听话药，是一种新型致幻药物 。本品为水剂，下在酒水里无色无味，与酒水搭配，真可谓珠联璧合，麻醉催眠效果更佳，药力见效快，喝下令人浑身瘫软四肢无力，出现短暂性失忆，只能任人摆布。"
