          "type": "text",
          "title": "",
          "text": "服用方法：您第一次服用的话，一次半颗，激发身体活力，然后3-4天一颗巩固效果，其后一般一周服用2颗就可以保持效果了！如果要效果您就一定要按说明服用。风靡东南亚的好产品。"
